$$

CREATE OR REPLACE PROCEDURE p_twice() RETURNS VARCHAR LANGUAGE JAVA PACKAGES=('com.snowflake:snowpark:latest') HANDLER='H.go' AS $$
import com.snowflake.snowpark_java.*;
class H { public String go(Session s) {
  DataFrame df = s.sql("INSERT INTO lazy_twice VALUES (1)");
  df.collect();
  long afterOne = s.sql("SELECT COUNT(*) FROM lazy_twice").collect()[0].getLong(0);
  df.collect();
  long afterTwo = s.sql("SELECT COUNT(*) FROM lazy_twice").collect()[0].getLong(0);
  return afterOne + "/" + afterTwo;
} }
$$

