CREATE OR REPLACE PROCEDURE p_table() RETURNS VARCHAR LANGUAGE JAVA PACKAGES=('com.snowflake:snowpark:latest') HANDLER='H.go' AS $$
import com.snowflake.snowpark_java.*;
class H { public String go(Session s) {
  DataFrame df = s.table("no_such_table_at_all");
  String built = df == null ? "null" : "plan";
  try { df.collect(); return built + "/no-error"; }
  catch (RuntimeException e) { return built + "/action-reported"; }
} }
$$

