CREATE OR REPLACE PROCEDURE p_rows() RETURNS VARCHAR LANGUAGE JAVA PACKAGES=('com.snowflake:snowpark:latest') HANDLER='H.go' AS $$
import com.snowflake.snowpark_java.*;
class H { public String go(Session s) {
  DataFrame df = s.sql("SELECT * FROM lazy_rows ORDER BY n");
  long c = df.count();
  Row[] first = df.collect();
  Row[] second = df.collect();
  return c + "/" + first.length + "/" + second.length + "/" + second[0].getInt(0);
} }
$$
